ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_RECT = "ارسم مستطيلاً عند (<b>x</b>, <b>y</b>) بحجم <b>w</b>×<b>h</b> باستخدام اللون <b>c</b>. إذا كان <b>f</b> صحيحًا، املأ المستطيل؛ وإلا ارسم فقط المحيط بعرض بكسل واحد.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_ELLIPSE = "ارسم قطعًا ناقصًا مركزه (<b>x</b>, <b>y</b>) بأنصاف أقطار <b>xr</b>, <b>yr</b> باستخدام اللون <b>c</b>. إذا كان <b>f</b> صحيحًا، املأه. المعامل الاختياري <b>m</b> يقيد الرسم إلى أرباع الدائرة عبر بتاته الأربعة الأقل.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_POLY = "ارسم مضلعًا مغلقًا بإزاحة (<b>x</b>, <b>y</b>) بناءً على أزواج الإحداثيات في <b>coords</b> (مِصفوفة <b>array</b> من أعداد صحيحة مثل <b>array('h', [x0, y0, x1, y1, ...])</b>) باستخدام اللون <b>c</b>. إذا كان <b>f</b> صحيحًا، املأه؛ وإلا ارسم المحيط.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_TEXT = "ارسم نصًا نقطيًا بحجم 8×8 <b>s</b> بحيث يكون ركنه الأيسر العلوي عند (<b>x</b>, <b>y</b>). الوسيطة الاختيارية <b>c</b> تحدد اللون (الافتراضي 1).";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_SCROLL = "حرك محتوى مخزن الإطارات بمقدار (<b>xstep</b>, <b>ystep</b>). لا تلتف البكسلات حول الحواف؛ قد تبقى الألوان القديمة في المناطق المكشوفة.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_BLIT = "انسخ مخزن إطارات آخر <b>fbuf</b> فوق هذا عند (<b>x</b>, <b>y</b>). إذا وُفِّر <b>key</b>، يُعامل ذلك اللون كقابل للشفافية. الوسيطة الاختيارية <b>palette</b> تُمكِّن النسخ بين صيغ مختلفة.";
